import unittest
from src.interval_tools import merge_intervals

class IntervalToolsTest(unittest.TestCase):
    def test_merge_intervals_overlaps_and_adjacency(self):
        self.assertEqual(merge_intervals([(5, 7), (1, 3), (3, 5), (10, 11)]), [(1, 7), (10, 11)])
        self.assertEqual(merge_intervals([(1, 2), (4, 6), (5, 8)]), [(1, 2), (4, 8)])
        self.assertEqual(merge_intervals([]), [])

    def test_rejects_reversed_interval(self):
        with self.assertRaises(ValueError):
            merge_intervals([(3, 1)])

if __name__ == '__main__':
    unittest.main()

