import unittest
from src.security_tools import redact_secrets

class SecurityToolsTest(unittest.TestCase):
    def test_redacts_supported_secret_shapes(self):
        text = 'key sk-abc123456789 token Bearer abc.def.ghi password=hunter2 PASSWORD=UpperCase ok'
        self.assertEqual(redact_secrets(text), 'key [REDACTED] token Bearer [REDACTED] password=[REDACTED] password=[REDACTED] ok')

    def test_leaves_unrelated_text(self):
        self.assertEqual(redact_secrets('no secrets here'), 'no secrets here')
        self.assertEqual(redact_secrets('sk-short Bearer'), 'sk-short Bearer')

if __name__ == '__main__':
    unittest.main()
